import React from "react"
import { AsyncContent, type AsyncContentEmptyProps } from "@sb-components/composites/async/AsyncContent/AsyncContent"
import { Grid, type GridItem } from "@sb-components/frames/Grid/Grid"
import { StackV } from "@sb-components/frames/Stack/Stack"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { ConsultantCard, type ConsultantCardConsultant } from "@sb-components/starci/blocks/consultant/ConsultantCard/ConsultantCard"

/**
 * `ConsultantDirectoryGrid` — the consultant directory's browse surface: a
 * match count above the cards, across the loading → empty → content lifecycle.
 * `AsyncContent` owns the branch switch, `Grid` the responsive track,
 * `ConsultantCard` one tile. The count line renders inside the `content` branch
 * only, beside real cards.
 */

/** Props for {@link ConsultantDirectoryGrid}. */
export interface ConsultantDirectoryGridProps {
    /**
     * The current page's consultants, already sorted by the caller. `undefined`
     * ⇒ the list has not resolved yet (see {@link ConsultantDirectoryGridProps.isLoading}).
     */
    consultants?: Array<ConsultantCardConsultant>
    /**
     * How many consultants the directory lists in total. `undefined` ⇒ the
     * count line does not render yet (see file header's judgement call).
     */
    count?: number
    /**
     * `true` while the consultant list's own fetch has not resolved. Passed
     * straight to `AsyncContent` — this block never infers it from
     * `consultants` itself (see file header).
     */
    isLoading: boolean
    /** Fired with a consultant's id when their card is pressed. */
    onOpenConsultant: (id: string) => void
    /** The empty-state message, already localized by the caller (see file header for why this stays a caller prop). */
    emptyTitle: string
    /** Accessible name for the directory region — the block has no visible heading of its own. */
    ariaLabel: string
}

/** How many placeholder tiles mirror the grid while the list hasn't resolved — ported from the real `ConsultantGrid`'s `SKELETON_COUNT`. */
const SKELETON_TILE_COUNT = 6

/** Skeleton tiles pass this as `onOpen` — `ConsultantCard.isSkeleton` disables its own press, so it never fires. */
const NOOP = () => {}

/** The block's own wording for the count line (§14d.1) — the caller only ever hands over a bare number. */
const countLabel = (count: number): string => `${count} consultants`

/**
 * The consultant directory's browse surface. See the file header for the full
 * contract and why the count line only shows beside real cards.
 *
 * @param props - {@link ConsultantDirectoryGridProps}
 */
const ConsultantDirectoryGrid = ({
    consultants,
    count,
    isLoading,
    onOpenConsultant,
    emptyTitle,
    ariaLabel,
}: ConsultantDirectoryGridProps) => {
    // Resolved-but-zero, matching the real `ConsultantGrid`'s Redux-driven gating
    // (`!consultants` = loading, `sortedConsultants.length === 0` = empty).
    const isEmpty = !isLoading && (consultants?.length ?? 0) === 0

    const skeletonTiles: Array<GridItem> = Array.from({ length: SKELETON_TILE_COUNT }, (_unused, index) => ({
        key: `skeleton-${index}`,
        content: () => (
            <ConsultantCard
                consultant={{ id: `skeleton-${index}`, fullName: "" }}
                onOpen={NOOP}
                isSkeleton


            />
        ),
    }))

    const tiles: Array<GridItem> = (consultants ?? []).map((consultant) => ({
        key: consultant.id,
        content: () => (
            <ConsultantCard
                consultant={consultant}
                onOpen={onOpenConsultant}


            />
        ),
    }))

    const emptyContent: AsyncContentEmptyProps = {
        title: emptyTitle,

    }

    return (
        <div role="region" aria-label={ariaLabel}>
            <AsyncContent
                isLoading={isLoading}
                skeleton={() => (
                    <Grid columns={{ base: 1, sm: 2, lg: 3 }} principle="content-row"
                        explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                        items={skeletonTiles}  />
                )}
                isEmpty={isEmpty}
                emptyContent={emptyContent}

                content={() => (
                    <StackV gap={4} principle="group-boundary"
                        explain="Section group spacing — not sibling-stack, because these blocks are distinct groups rather than same-kind peers."
                        items={[
                            ...(count !== undefined ? [() => (
                                <Typography size="sm" color="muted" text={countLabel(count)} />
                            )] : []),
                            () => (
                                <Grid columns={{ base: 1, sm: 2, lg: 3 }} principle="content-row"
                                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                    items={tiles}  />
                            ),
                        ]} />
                )}
            />
        </div>
    )
}

export { ConsultantDirectoryGrid }

import React from "react"
import {
    SearchAutocomplete,
    type SearchAutocompleteItem,
} from "@/components/atoms/forms/SearchAutocomplete"

/**
 * `ConsultantDirectoryCompanySearch` — a typed, debounced deep-link to one
 * recruiting company's page, sitting above the consultant grid on the directory
 * screen. It is not a grid filter: there is no server-side search over
 * consultants, only a company suggester, so it jumps straight to a known
 * company page. `isLoadingSuggestions` swaps the popover's content.
 */

/** One company the ES suggester matched against the typed query. */
export interface ConsultantCompanySuggestion {
    /** Stable company id — the payload handed back through `onSelectCompany`. */
    id: string
    /** Company display name, already localized/formatted by the caller. */
    label: string
}

/** Props for {@link ConsultantDirectoryCompanySearch}. */
export interface ConsultantDirectoryCompanySearchProps {
    /** Current text in the search field (controlled). */
    query: string
    /** Fired with the new query on every keystroke; the screen owns debouncing. */
    onQueryChange: (value: string) => void
    /** Company matches for the current query, already fetched by the screen. */
    suggestions: Array<ConsultantCompanySuggestion>
    /** `true` while the screen is waiting on the ES company-suggester. */
    isLoadingSuggestions?: boolean
    /** Fired with the picked company's id; the screen owns the route push. */
    onSelectCompany: (companyId: string) => void
}

/**
 * The company deep-link search row atop the consultant directory. See the file
 * header for why this is a jump-to-company control and not a grid filter.
 *
 * @param props - {@link ConsultantDirectoryCompanySearchProps}
 */
const ConsultantDirectoryCompanySearch = ({
    query,
    onQueryChange,
    suggestions,
    isLoadingSuggestions = false,
    onSelectCompany,
}: ConsultantDirectoryCompanySearchProps) => {
    const items: Array<SearchAutocompleteItem> = suggestions.map((company) => ({
        id: company.id,
        label: company.label,
    }))

    // Sole root is SearchAutocomplete — inert host wrappers removed. Identity
    // stays held until the atom accepts CallerIdentity (CourseTrialChip pattern).
    return (
        <SearchAutocomplete
            items={items}
            inputValue={query}
            onInputChange={onQueryChange}
            onSelect={onSelectCompany}
            isLoading={isLoadingSuggestions}
            // Owned wording: this field jumps to ONE company, it does not filter
            // the grid below it — the placeholder has to say so or a visitor will
            // type a role/skill and get nothing back.
            placeholder="Search for a hiring company by name…"
            emptyLabel="No companies found"
        />
    )
}

export { ConsultantDirectoryCompanySearch }

