"use client"

import React from "react"
import { Button, Input, Label, TextField } from "@heroui/react"
import { useTranslations } from "next-intl"
import { PlusIcon } from "@phosphor-icons/react"
import type { CvBlock, CvBlockEditorProps, CvBlockItem } from "@/modules/types/entities/cv"
import { StackV } from "@/components/frames/Stack"
import { RepeatableItemCard } from "../shared/RepeatableItemCard"

/** A brand-new, empty achievement entry. */
const emptyItem = (): CvBlockItem => ({ id: crypto.randomUUID(), fields: {} })

/** Props for {@link AchievementBlockEditor}. */
export type AchievementBlockEditorProps = CvBlockEditorProps 

/**
 * Freeform achievements block editor (outside awards, certifications) —
 * repeatable, self-reported, never scored. No AI affordance (per
 * `CV_BLOCK_TYPE_REGISTRY[Achievement]`).
 *
 * Shell is StackV with identity. HeroUI TextField/Input/Button remain —
 * house form migration is contract `CvBlockEditorFormSurface` (vendor boundary).
 *
 * @param props - {@link AchievementBlockEditorProps}
 */
export const AchievementBlockEditor = ({ block, onChange }: AchievementBlockEditorProps) => {
    const t = useTranslations()

    const setItems = (items: Array<CvBlockItem>) => onChange({ ...block, items } satisfies CvBlock)

    const onFieldChange = (itemId: string, key: string, value: string) => {
        setItems(block.items.map((item) => (
            item.id === itemId ? { ...item, fields: { ...item.fields, [key]: value } } : item
        )))
    }

    const onAddItem = () => setItems([...block.items, emptyItem()])
    const onRemoveItem = (itemId: string) => setItems(block.items.filter((item) => item.id !== itemId))
    const onMove = (index: number, direction: -1 | 1) => {
        const next = [...block.items]
        const target = index + direction
        if (target < 0 || target >= next.length) {
            return
        }
        [next[index], next[target]] = [next[target], next[index]]
        setItems(next)
    }

    const itemCount = block.items.length

    return (
        <StackV
            gap={3}
            identity={{ tier: "block", component: "AchievementBlockEditor" }}
            principle="sibling-stack"
            explain="Same-kind peer stack of repeatable achievement cards — not group-boundary, because each card is a repeating peer rather than a section group."
            items={[
                ...block.items.map((item, index) => () => (
                    <RepeatableItemCard
                        onRemove={() => onRemoveItem(item.id)}
                        onMoveUp={index > 0 ? () => onMove(index, -1) : undefined}
                        onMoveDown={index < itemCount - 1 ? () => onMove(index, 1) : undefined}
                    >
                        <TextField variant="secondary">
                            <Label htmlFor={`cv-achievement-title-${item.id}`}>
                                {t("cv.blocks.achievement.fields.title")}
                            </Label>
                            <Input
                                id={`cv-achievement-title-${item.id}`}
                                placeholder={t("cv.blocks.achievement.placeholders.title")}
                                value={typeof item.fields.title === "string" ? item.fields.title : ""}
                                onChange={(event) => onFieldChange(item.id, "title", event.target.value)}
                            />
                        </TextField>
                        <TextField variant="secondary">
                            <Label htmlFor={`cv-achievement-description-${item.id}`}>
                                {t("cv.blocks.achievement.fields.description")}
                            </Label>
                            <Input
                                id={`cv-achievement-description-${item.id}`}
                                placeholder={t("cv.blocks.achievement.placeholders.description")}
                                value={typeof item.fields.description === "string" ? item.fields.description : ""}
                                onChange={(event) => onFieldChange(item.id, "description", event.target.value)}
                            />
                        </TextField>
                    </RepeatableItemCard>
                )),
                () => (
                    <Button variant="tertiary" size="sm" className="w-fit self-start" onPress={onAddItem}>
                        <PlusIcon aria-hidden className="size-4" />
                        {t("cv.blocks.achievement.addItem")}
                    </Button>
                ),
            ]}
        />
    )
}

"use client"

import React, { useState } from "react"
import { Calendar, DateField, DatePicker, FieldError, Input, Label, TextField } from "@heroui/react"
import { getLocalTimeZone, parseDate, today } from "@internationalized/date"
import type { DateValue } from "@internationalized/date"
import { useTranslations } from "next-intl"
import type { CvBlockEditorProps } from "@/modules/types/entities/cv"
import { isValidOptionalUrl } from "@/modules/utils/cv-url"
import { Grid, type GridItem } from "@/components/frames/Grid"

/** Field keys read/written on the single `personal` item's `fields`. */
const FIELD_KEYS = [
    "name",
    "role",
    "email",
    "phone",
    "location",
    "birthDate",
    "linkedinUrl",
    "githubUsername",
] as const
type PersonalFieldKey = typeof FIELD_KEYS[number]

/** The only field key validated as a URL (blur-triggered, per `isValidOptionalUrl`). */
const URL_FIELD_KEYS: ReadonlySet<PersonalFieldKey> = new Set(["linkedinUrl"])

/** Parses a stored ISO date string (e.g. `"2000-01-01"`) into a `DateValue`, or `null` if empty/unparseable. */
const parseStoredDate = (value: string): DateValue | null => {
    if (!value) {
        return null
    }
    try {
        return parseDate(value)
    } catch {
        return null
    }
}

/** Props for {@link PersonalBlockEditor}. */
export type PersonalBlockEditorProps = CvBlockEditorProps 

/**
 * Header/contact block editor — singleton, non-repeatable, no AI affordance
 * (per `CV_BLOCK_TYPE_REGISTRY[Personal]`). Holds its one fields set on
 * `block.items[0]` (created on first edit if the block starts with 0 items,
 * per the uniform `CvBlock` shape every block type shares).
 *
 * @param props - {@link PersonalBlockEditorProps}
 */
export const PersonalBlockEditor = ({ block, onChange }: PersonalBlockEditorProps) => {
    const t = useTranslations()
    const fields = block.items[0]?.fields ?? {}
    const [touchedUrlKeys, setTouchedUrlKeys] = useState<ReadonlySet<PersonalFieldKey>>(new Set())

    const onFieldChange = (key: PersonalFieldKey, value: string) => {
        const item = block.items[0] ?? { id: crypto.randomUUID(), fields: {} }
        const nextItem = { ...item, fields: { ...item.fields, [key]: value } }
        onChange({ ...block, items: [nextItem] })
    }

    const onBlurUrlField = (key: PersonalFieldKey) => {
        setTouchedUrlKeys((prev) => new Set(prev).add(key))
    }

    // Shell is Grid with identity. HeroUI DatePicker/TextField remain —
    // house form migration is contract `CvBlockEditorFormSurface` (vendor boundary).
    const items: Array<GridItem> = FIELD_KEYS.map((key) => {
        const value = typeof fields[key] === "string" ? (fields[key] as string) : ""

        if (key === "birthDate") {
            return {
                key,
                content: () => (
                    <DatePicker
                        aria-label={t("cv.blocks.personal.fields.birthDate")}
                        maxValue={today(getLocalTimeZone())}
                        value={parseStoredDate(value)}
                        onChange={(date) => onFieldChange(key, date ? date.toString() : "")}
                    >
                        <Label>{t("cv.blocks.personal.fields.birthDate")}</Label>
                        <DateField.Group fullWidth variant="secondary">
                            <DateField.Input>
                                {(segment) => <DateField.Segment segment={segment} />}
                            </DateField.Input>
                            <DateField.Suffix>
                                <DatePicker.Trigger>
                                    <DatePicker.TriggerIndicator />
                                </DatePicker.Trigger>
                            </DateField.Suffix>
                        </DateField.Group>
                        <DatePicker.Popover>
                            <Calendar aria-label={t("cv.blocks.personal.fields.birthDate")}>
                                <Calendar.Header>
                                    <Calendar.YearPickerTrigger>
                                        <Calendar.YearPickerTriggerHeading />
                                        <Calendar.YearPickerTriggerIndicator />
                                    </Calendar.YearPickerTrigger>
                                    <Calendar.NavButton slot="previous" />
                                    <Calendar.NavButton slot="next" />
                                </Calendar.Header>
                                <Calendar.Grid>
                                    <Calendar.GridHeader>
                                        {(day) => <Calendar.HeaderCell>{day}</Calendar.HeaderCell>}
                                    </Calendar.GridHeader>
                                    <Calendar.GridBody>
                                        {(date) => <Calendar.Cell date={date} />}
                                    </Calendar.GridBody>
                                </Calendar.Grid>
                                <Calendar.YearPickerGrid>
                                    <Calendar.YearPickerGridBody>
                                        {({ year }) => <Calendar.YearPickerCell year={year} />}
                                    </Calendar.YearPickerGridBody>
                                </Calendar.YearPickerGrid>
                            </Calendar>
                        </DatePicker.Popover>
                    </DatePicker>
                ),
            }
        }

        const isUrlField = URL_FIELD_KEYS.has(key)
        const isInvalid = isUrlField && touchedUrlKeys.has(key) && !isValidOptionalUrl(value)
        return {
            key,
            content: () => (
                <TextField variant="secondary" isInvalid={isInvalid}>
                    <Label htmlFor={`cv-personal-${key}`}>
                        {t(`cv.blocks.personal.fields.${key}`)}
                    </Label>
                    <Input
                        id={`cv-personal-${key}`}
                        placeholder={t(`cv.blocks.personal.placeholders.${key}`)}
                        value={value}
                        onChange={(event) => onFieldChange(key, event.target.value)}
                        onBlur={isUrlField ? () => onBlurUrlField(key) : undefined}
                    />
                    {isUrlField ? (
                        <FieldError>{t("cv.blocks.common.invalidUrl")}</FieldError>
                    ) : null}
                </TextField>
            ),
        }
    })

    return (
        <Grid
            identity={{ tier: "block", component: "PersonalBlockEditor" }}
            columns={{ base: 1, sm: 3 }}
            principle="sibling-stack"
            explain="Same-kind peer field cells — not group-boundary, because each field is a repeating peer rather than a section group."
            items={items}
        />
    )
}

"use client"

import React from "react"
import { useTranslations } from "next-intl"
import {
    CV_TWO_COLUMN_TEMPLATES,
    type CvDocument,
    type CvTemplate,
} from "@/modules/types/entities/cv"
import { Chip } from "@/components/atoms/chips/Chip"
import { Typography } from "@/components/atoms/text/Typography"
import { SurfaceCard } from "@/components/composites/cards/SurfaceCard"
import { ModalShell } from "@/components/composites/layout/ModalShell"
import { Grid, type GridItem } from "@/components/frames/Grid"
import { StackH, StackV } from "@/components/frames/Stack"
import { CvHtmlDocument } from "../CvHtmlDocument"

/** The templates the gallery offers, in display order. */
const TEMPLATE_ORDER: ReadonlyArray<CvTemplate> = ["classic", "modern", "sidebar", "minimal"]

/** Props for {@link CvTemplateGalleryModal}. */
export interface CvTemplateGalleryModalProps {
    /** Whether the modal is open. */
    isOpen: boolean
    /** Fired when the modal should open/close. */
    onOpenChange: (isOpen: boolean) => void
    /** The active document — its data feeds every live thumbnail. */
    doc: CvDocument
    /** Fired with the picked template; the caller applies it to `style` + closes. */
    onSelect: (template: CvTemplate) => void
}

/**
 * "Template Gallery" — a modal grid of LIVE template thumbnails (the user's own CvGalleryPage
 * rendered in each layout via {@link CvHtmlDocument}) + name + an ATS badge.
 * Single-column templates read "ATS-safe"; the two-column one carries a
 * warning (ATS parsers + `.docx` export handle it worse — see
 * `CvGalleryPage-TEMPLATES-BRAINSTORM.md`). Picking a card applies the template and closes.
 *
 * Thumbnail mount (`width: 820` + `scale(0.34)` + fixed `h-52` crop) has no finite
 * vocabulary owner — held as contract proposal `CvTemplateThumbMount`, not rewritten.
 *
 * @param props - {@link CvTemplateGalleryModalProps}
 */
export const CvTemplateGalleryModal = ({
    isOpen,
    onOpenChange,
    doc,
    onSelect}: CvTemplateGalleryModalProps) => {
    const t = useTranslations()
    const current = doc.style.template ?? "classic"

    const onPick = (template: CvTemplate) => {
        onSelect(template)
        onOpenChange(false)
    }

    const items: Array<GridItem> = TEMPLATE_ORDER.map((template) => {
        const isTwoColumn = CV_TWO_COLUMN_TEMPLATES.has(template)
        const isSelected = current === template
        const name = t(`cv.builder.template.names.${template}`)
        return {
            key: template,
            content: () => (
                <SurfaceCard
                    isSelected={isSelected}
                    onPress={() => onPick(template)}
                    ariaLabel={t("cv.builder.template.selectAria", { name })}
                    body={() => (
                        <StackV
                            principle="card-caption"
                            explain="Thumbnail crop over template caption row — not sibling-stack, because the caption belongs to the media above it."
                            items={[
                                () => (
                                    // HOLD: CvTemplateThumbMount — live HTML CV scaled into a
                                    // fixed crop. No Measure/PDFView enum owns scale(0.34)×820px.
                                    <div aria-hidden className="h-52 overflow-hidden border-b border-default bg-white">
                                        <div
                                            className="pointer-events-none origin-top-left"
                                            style={{ width: 820, transform: "scale(0.34)" }}
                                        >
                                            <CvHtmlDocument doc={{ ...doc, style: { ...doc.style, template } }} />
                                        </div>
                                    </div>
                                ),
                                () => (
                                    <StackH
                                        gap={2}
                                        principle="content-row"
                                        explain="Keeps template name and ATS chip on one baseline so the chip does not drop under the title."
                                        items={[
                                            () => (
                                                <StackV
                                                    gap={1}
                                                    principle="title-subtitle"
                                                    explain="Template name over optional Word hint — not label-field, because neither line is a form control."
                                                    items={[
                                                        () => (
                                                            <Typography
                                                                size="sm"
                                                                weight="semibold"
                                                                truncate
                                                                text={name}
                                                            />
                                                        ),
                                                        ...(isTwoColumn
                                                            ? [
                                                                () => (
                                                                    <Typography
                                                                        size="xs"
                                                                        color="muted"
                                                                        text={t("cv.builder.template.wordHint")}
                                                                    />
                                                                ),
                                                            ]
                                                            : []),
                                                    ]}
                                                />
                                            ),
                                            () => (
                                                <Chip
                                                    tone={isTwoColumn ? "warning" : "success"}
                                                    text={isTwoColumn ? t("cv.builder.template.atsRisk") : t("cv.builder.template.atsSafe")}
                                                />
                                            ),
                                        ]}
                                    />
                                ),
                            ]}
                        />
                    )}
                />
            ),
        }
    })

    return (
        <ModalShell
            identity={{ tier: "block", component: "CvTemplateGalleryModal" }}
            isOpen={isOpen}
            onOpenChange={onOpenChange}
            title={t("cv.builder.template.galleryTitle")}
            size="lg"
            body={() => (
                <Grid
                    columns={{ base: 1, sm: 2 }}
                    principle="sibling-stack"
                    explain="Same-kind peer template tiles — not group-boundary, because each card is a repeating peer rather than a section group."
                    items={items}
                />
            )}
        />
    )
}

"use client"

import React, {
    useCallback,
    useState,
} from "react"
import { toast } from "@/modules/toast/toast"
import { useTranslations } from "next-intl"
import type {
    CvSubmissionFormValues,
} from "@/types"
import { mutateGetCVPresignedUrl } from "@/modules/api/graphql/mutations/mutation-get-cv-presigned-url"
import { mutateProcessCV } from "@/modules/api/graphql/mutations/mutation-process-cv"
import { useAppSelector } from "@/redux/hooks"
import { CVSubmissionForm } from "@/components/blocks/careers/CVSubmissionForm"
import { useRestWithToast } from "@/modules/toast/hooks"

/** Fraction of progress shown after each upload step (UI feedback only). */
const UPLOAD_PROGRESS = {
    /** Presigned-URL request issued. */
    presign: 20,
    /** S3 PUT in flight. */
    uploading: 40,
    /** Upload finished. */
    done: 100,
} as const

/** Props for {@link CvSubmission}. */
export type CvSubmissionProps = Record<string, never>
/**
 * CV submission container.
 *
 * Owns the business logic — auth token (redux), upload/process state, the
 * presigned-URL + S3 upload + process mutations — and renders the presentational
 * {@link CVSubmissionForm}. `"use client"` because it holds state + side effects.
 * @param props - {@link CvSubmissionProps}
 */
export const CvSubmission = () => {
    /** Keycloak access token used to authorize the API calls. */
    const token = useAppSelector((state) => state.keycloak.accessToken)
    /** Whether the S3 upload step is in progress. */
    const [isUploading, setIsUploading] = useState(false)
    /** Whether the backend processing step is in progress. */
    const [isProcessing, setIsProcessing] = useState(false)
    /** Upload progress percentage (0–100). */
    const [uploadProgress, setUploadProgress] = useState(0)
    /** Name of the successfully uploaded file, or `null`. */
    const [uploadedFileName, setUploadedFileName] = useState<string | null>(null)
    /** S3 key of the successfully uploaded file, or `null`. */
    const [uploadedS3Key, setUploadedS3Key] = useState<string | null>(null)
    /** Localized toast wrapper for REST calls. */
    const runRest = useRestWithToast()
    const t = useTranslations("cv.submission")

    /** Upload the selected CV to S3 via a presigned URL. */
    const onSubmit = useCallback(
        async (
            values: CvSubmissionFormValues,
        ) => {
            if (!token) {
                console.error("Authentication token not found")
                return
            }
            if (!values.cv) {
                console.error("CV file is required")
                return
            }

            try {
                setIsUploading(true)
                setUploadProgress(0)
                setUploadedFileName(null)
                setUploadedS3Key(null)

                // Step 1: get a presigned URL from the backend
                setUploadProgress(UPLOAD_PROGRESS.presign)
                const presignedUrlResponse = await mutateGetCVPresignedUrl({
                    request: {
                        fileName: values.cv.name,
                        fileType: values.cv.type,
                    },
                    token,
                })
                if (!presignedUrlResponse.data?.getCVPresignedUrl?.data) {
                    throw new Error(
                        presignedUrlResponse.data?.getCVPresignedUrl?.message
                            || "Failed to get presigned URL",
                    )
                }
                const {
                    url: presignedUrl,
                    key: s3Key,
                } = presignedUrlResponse.data.getCVPresignedUrl.data

                // Step 2: upload the file to S3 via PUT
                setUploadProgress(UPLOAD_PROGRESS.uploading)
                const cvFile = values.cv
                const uploadResponse = await runRest(
                    async () => {
                        const response = await fetch(presignedUrl, {
                            method: "PUT",
                            body: cvFile,
                            headers: {
                                "Content-Type": cvFile.type,
                            },
                        })
                        if (!response.ok) {
                            throw new Error(
                                `Failed to upload file to S3: ${response.statusText}`,
                            )
                        }
                        return response
                    },
                    {
                        showSuccessToast: false,
                    },
                )
                if (!uploadResponse) {
                    return
                }

                setUploadProgress(UPLOAD_PROGRESS.done)
                setUploadedFileName(values.cv.name)
                setUploadedS3Key(s3Key)
                // the form resets itself via a useEffect once these two props are set
            } catch (error) {
                console.error("CV upload error:", error)
                toast.danger(t("uploadError"))
            } finally {
                setIsUploading(false)
            }
        },
        [
            token,
            runRest,
            t,
        ],
    )

    /** Trigger backend processing of the previously uploaded CV. */
    const onProcess = useCallback(
        async () => {
            if (!token) {
                console.error("Authentication token not found")
                return
            }
            if (!uploadedS3Key || !uploadedFileName) {
                console.error("Please upload CV first")
                return
            }

            try {
                setIsProcessing(true)
                const processResponse = await mutateProcessCV({
                    request: {
                        s3Key: uploadedS3Key,
                        fileName: uploadedFileName,
                    },
                    token,
                })
                if (!processResponse.data?.processCV?.data) {
                    throw new Error(
                        processResponse.data?.processCV?.message
                            || "Failed to process CV",
                    )
                }
            } catch (error) {
                console.error("CV process error:", error)
                toast.danger(t("processError"))
            } finally {
                setIsProcessing(false)
            }
        },
        [
            token,
            uploadedS3Key,
            uploadedFileName,
            t,
        ],
    )

    // CVSubmissionForm already stamps block identity — promote it to the root.
    return (
        <CVSubmissionForm
            isUploading={isUploading}
            isProcessing={isProcessing}
            uploadProgress={uploadProgress}
            uploadedFileName={uploadedFileName}
            uploadedS3Key={uploadedS3Key}
            onSubmit={onSubmit}
            onProcess={onProcess}
        />
    )
}

import React from "react"
import { ShareNetworkIcon } from "@phosphor-icons/react"
import { Button } from "@/components/atoms/buttons/Button"

/** Props for {@link ShareProfileButton}. */
export interface ShareProfileButtonProps {
    /** Fired when the share action is pressed. */
    onShare?: () => void
    /** `true` → icon-only shimmer; no press. */
    isSkeleton?: boolean
}

/**
 * Icon-only share trigger — the caller decides what "share" does (copy link, open a sheet, …).
 * Atom Button root — CallerIdentity held until atoms accept it (CourseTrialChip pattern).
 *
 * @param props - {@link ShareProfileButtonProps}
 */
export const ShareProfileButton = ({ onShare, isSkeleton = false}: ShareProfileButtonProps) => {
    if (isSkeleton) {
        return <Button isSkeleton isIconOnly />
    }
    return (
        <Button
            isIconOnly
            variant="tertiary"
            prefixIcon={ShareNetworkIcon}
            ariaLabel="Share profile"
            onPress={onShare}

        />
    )
}
